---
import { getCollection, render } from "astro:content";
import Layout from "../../layouts/Layout.astro";
import { AUDIO_BASE } from "../../consts";

export async function getStaticPaths() {
  const articles = await getCollection("articles", ({ data }) => import.meta.env.DEV || !data.draft);
  return articles.map((article) => ({ params: { slug: article.id }, props: { article } }));
}

const { article } = Astro.props;
const { title, description, pubDate, narrated } = article.data;
const { Content } = await render(article);

const jsonLd = {
  "@context": "https://schema.org",
  "@type": "BlogPosting",
  headline: title,
  description,
  datePublished: pubDate.toISOString(),
  author: { "@type": "Person", name: "Sara Natour", url: Astro.site },
  mainEntityOfPage: new URL(Astro.url.pathname, Astro.site),
};
---

<Layout title={`${title} | Sara Natour`} description={description} type="article">
  <main class="w-full max-w-200 mx-auto">
    <header class="mb-6">
      <h1 class="text-3xl text-black-1">{title}</h1>
      <time class="text-sm text-neutral-600" datetime={pubDate.toISOString()}>
        {pubDate.toLocaleDateString("en", { dateStyle: "long" })}
      </time>
    </header>
    {
      narrated && (
        <audio data-narration controls preload="metadata" src={`${AUDIO_BASE}/${article.id}.mp3`} class="sticky top-2 z-10 w-full mb-6">
          <track kind="metadata" src={`/narration/${article.id}.vtt`} default />
        </audio>
      )
    }
    <article data-article class="prose prose-neutral max-w-none">
      <Content />
    </article>
  </main>
  <script type="application/ld+json" is:inline set:html={JSON.stringify(jsonLd)} />
</Layout>

<style is:global>
  ::highlight(narration) {
    background-color: color-mix(in srgb, var(--color-blue-1) 30%, transparent);
  }
</style>

<script>
  // Follows the narration: each cue in the .vtt is one sentence; the matching
  // sentence on the page is highlighted (CSS Custom Highlight API, no markup added).
  const norm = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");

  document.addEventListener("astro:page-load", () => {
    CSS.highlights?.delete("narration");
    const audio = document.querySelector<HTMLAudioElement>("audio[data-narration]");
    const article = document.querySelector("article[data-article]");
    const track = audio?.textTracks[0];
    if (!audio || !article || !track || !CSS.highlights) return; // plain player, no highlighting

    // One Range per sentence, in page order.
    const segmenter = new Intl.Segmenter("en", { granularity: "sentence" });
    const sentences: { key: string; range: Range }[] = [];
    for (const block of article.querySelectorAll("p, h2, h3, h4, li")) {
      if (block.closest("pre") || block.querySelector("p")) continue;
      const walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT);
      const nodes: Text[] = [];
      while (walker.nextNode()) nodes.push(walker.currentNode as Text);
      const at = (offset: number): [Text, number] => {
        for (const node of nodes) {
          if (offset <= node.length) return [node, offset];
          offset -= node.length;
        }
        return [nodes[nodes.length - 1], nodes[nodes.length - 1].length];
      };
      for (const { segment, index } of segmenter.segment(block.textContent ?? "")) {
        const key = norm(segment);
        if (!key) continue;
        const range = new Range();
        range.setStart(...at(index));
        range.setEnd(...at(index + segment.trimEnd().length));
        sentences.push({ key, range });
      }
    }

    // Cues are matched to sentences by text, in order, so editing the article
    // after recording only un-highlights the edited sentence.
    let byCue: Map<TextTrackCue, Range> | undefined;
    const matchCues = () => {
      byCue = new Map();
      let from = 0;
      for (const cue of track.cues ?? []) {
        const key = norm((cue as VTTCue).getCueAsHTML().textContent ?? "");
        const i = sentences.findIndex((s, i) => i >= from && s.key === key);
        if (i < 0) continue;
        byCue.set(cue, sentences[i].range);
        from = i + 1;
      }
    };

    const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
    track.mode = "hidden"; // load cues and fire cuechange without rendering them
    track.addEventListener("cuechange", () => {
      if (!byCue) matchCues();
      const cue = track.activeCues?.[0];
      const range = cue && byCue!.get(cue);
      if (!range) return;
      CSS.highlights.set("narration", new Highlight(range));
      if (!audio.paused) {
        range.startContainer.parentElement?.scrollIntoView({
          block: "center",
          behavior: reducedMotion.matches ? "auto" : "smooth",
        });
      }
    });
  });
</script>
EOF
cat > src/pages/rss.xml.js <<'EOF'
import rss from "@astrojs/rss";
import { getCollection } from "astro:content";

export async function GET(context) {
  const articles = await getCollection("articles", ({ data }) => !data.draft);
  return rss({
    title: "Sara Natour",
    description: "Articles by Sara Natour.",
    site: context.site,
    items: articles
      .sort((a, b) => b.data.pubDate.valueOf() - a.data.pubDate.valueOf())
      .map(({ id, data }) => ({
        title: data.title,
        description: data.description,
        pubDate: data.pubDate,
        link: `/articles/${id}/`,
      })),
  });
}
EOF
cat > scripts/align.mjs <<'EOF'
#!/usr/bin/env node
// Writes public/narration/<slug>.vtt: one cue per sentence of the article,
// timed against your recording by forced alignment (stable-ts / Whisper).
//
//   node scripts/align.mjs <slug>            # reads public/audio/<slug>.mp3
//   node scripts/align.mjs <slug> --dry-run  # just print the sentences
//
// Needs `uv` (brew install uv) and ffmpeg. First run downloads a Whisper model.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// ponytail: regex markdown stripping, not a real parser. A sentence it gets
// wrong just isn't highlighted (the page matches cues by text). Swap in
// remark if articles start using heavy MDX.
export function sentences(mdx) {
  const text = mdx
    .replace(/^---\n[\s\S]*?\n---\n/, "") // frontmatter
    .replace(/^```[\s\S]*?^```/gm, "") // code fences
    .replace(/^(import|export) .*$/gm, "")
    .replace(/<[^>]+>/g, "") // JSX / HTML tags
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "") // images
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1") // links -> their text
    .replace(/^\s*(#{1,6}|>|[-*+]|\d+\.)\s+/gm, "\n") // block markers start a new block
    .replace(/[*_`~]/g, "")
    .replace(/([^\n])\n(?!\n)/g, "$1 "); // hard-wrapped lines are one paragraph
  const segmenter = new Intl.Segmenter("en", { granularity: "sentence" });
  return text
    .split(/\n+/)
    .flatMap((block) => [...segmenter.segment(block)].map((s) => s.segment.trim()))
    .filter((s) => /[\p{L}\p{N}]/u.test(s));
}

function selfCheck() {
  const got = sentences(
    "---\ntitle: x\n---\n\n## A heading\n\nFirst *one*. Second,\nwrapped [link](http://x).\n\n- item\n\n```js\ncode. here.\n```\n",
  );
  const want = ["A heading", "First one.", "Second, wrapped link.", "item"];
  if (JSON.stringify(got) !== JSON.stringify(want)) throw new Error(`sentences() self-check failed: ${JSON.stringify(got)}`);
}

if (import.meta.filename === process.argv[1]) {
  selfCheck();
  const [slug, flag] = process.argv.slice(2);
  if (!slug) {
    console.error("usage: node scripts/align.mjs <slug> [--dry-run]");
    process.exit(1);
  }
  const lines = sentences(readFileSync(`src/content/articles/${slug}.mdx`, "utf8"));
  if (flag === "--dry-run") {
    console.log(lines.join("\n"));
    process.exit(0);
  }
  const textFile = join(mkdtempSync(join(tmpdir(), "align-")), "text.txt");
  writeFileSync(textFile, lines.join("\n"));
  const out = `public/narration/${slug}.vtt`;
  execFileSync(
    "uvx",
    ["--from", "stable-ts", "stable-ts", `public/audio/${slug}.mp3`, "--align", textFile, "--language", "en",
      "--original_split", "true", "--word_level", "false", "--overwrite", "-o", out],
    { stdio: "inherit" },
  );
  const cues = (readFileSync(out, "utf8").match(/-->/g) ?? []).length;
  if (cues !== lines.length) {
    console.error(`\n${out}: ${cues} cues for ${lines.length} sentences. Check the file; sentences without a matching cue won't be highlighted.`);
    process.exit(1);
  }
  console.log(`\n${out}: ${cues} cues. Upload the audio:\n  pnpm wrangler r2 object put site-audio/${slug}.mp3 --file public/audio/${slug}.mp3 --remote`);
}
EOF
node scripts/align.mjs hello-narration --dry-run
printf '\n# local narration recordings (hosted on R2, see scripts/align.mjs)\npublic/audio/\n' >> .gitignore

