   135	      audio.hidden = true;
   136	      player.hidden = false;
   137	      for (const event of ["loadedmetadata", "timeupdate", "play", "pause", "ended"]) audio.addEventListener(event, sync);
   138	      play.addEventListener("click", () => (audio.paused ? audio.play() : audio.pause()));
   139	      seek.addEventListener("input", () => (audio.currentTime = Number(seek.value)));
   140	      rate.addEventListener("click", () => {
   141	        const speeds = [1, 1.25, 1.5, 2];
